"""Run the ORIGINAL NR2003 vehicle runtime (JIT callbacks generated by the game itself) in Unicorn.
Per tick, exactly the order of 005b2190: inputs->predictor+solve (005b2b90), tires (0055e1e0 x4),
forces (005b2bd0), corrector+solve (005b2be0), tires, forces, commit (005b2c00), export (005b2cd0).
Host-provided contact = per-wheel plane (n, d) in vehicle-world axes (+X fwd, +Y left, +Z up),
ground velocity, surface index; exactly the arguments the track code passes to 0055e1e0."""
import struct
from orig_vehicle import *

GAME_FPCW = 0x077f   # main loop 00546f80 forces RC=down(1), PC=64-bit(3) via 00567704(1,3)
STATE = 0xbf6d40     # 45 float state block (005b2cd0 export / 005b4560 import order)
INPUT = 0xbf6360     # 9 floats -> e84474 cells: lfSteer, rfSteer, throttle, brake, clutch, gear, -, -, -

class Original:
    def __init__(self, chassis_type=CHASSIS_TYPE, state=None, log=lambda *a: None):
        self.m = m = boot()
        self.state0 = state
        if state is not None:
            for i, v in enumerate(state): m.wf(STATE + 4 * i, v)
        m.fpcw = GAME_FPCW
        self.spec, self.root = build(m, chassis_type, log=log)
        m.uc.mem_write(BG_FLAG, b'\x01')     # physics runs on the background (sim) task thread
        # per-wheel persistent contact block (param_5 of 0055e1e0: anchor xyz + 2 tire state floats)
        self.blocks = [m.alloc(20) for _ in range(4)]
        self.outF = [m.alloc(12) for _ in range(4)]
        self.outP = [m.alloc(12) for _ in range(4)]
        self.gv = [m.alloc(12) for _ in range(4)]
        self.ret = [0.0] * 4

    def state(self):
        m = self.m; m.w32(0xe847c8, STATE); m.call(0x5b2cb0, STATE, self.root)
        return [m.f32(STATE + 4 * i) for i in range(45)]

    def tires(self, contacts):
        m = self.m
        for i, c in enumerate(contacts):
            n, d = c['normal'], c['d']
            gv = c.get('groundVelocity', (0, 0, 0))
            for k in range(3): m.wf(self.gv[i] + 4 * k, gv[k])
            sp = STACK_TOP - 0x1000
            # 0055e1e0 is cdecl with 11 args; floats passed as raw 32-bit values
            args = [self.outF[i], bits(c.get('grip', 1.0)), self.outP[i], self.gv[i], self.blocks[i], i,
                    bits(n[0]), bits(n[1]), bits(n[2]), bits(d), c.get('surface', 1)]
            m.call(0x55e1e0, *args)
            self.ret[i] = m.st0()

    def step(self, inputs, contacts):
        m = self.m
        vals = [inputs.get(k, 0.0) for k in ('lfSteer', 'rfSteer', 'throttle', 'brake', 'clutch', 'gear')] + [0.0] * 3
        for i, v in enumerate(vals): m.wf(INPUT + 4 * i, v)
        m.uc.mem_write(0xe843fc, b'\x01')          # 005b2190: predictor pass flag
        m.call(0x5b2b90, self.root, INPUT)
        self.tires(contacts); m.call(0x5b2bd0)
        m.uc.mem_write(0xe843fc, b'\x00')
        m.call(0x5b2be0)
        self.tires(contacts); m.call(0x5b2bd0)
        m.call(0x5b2c00)
        self.tick = getattr(self, 'tick', 0) + 1
        if self.tick % 8 == 0: engine_frame(m)       # 288 Hz physics / 36 Hz task frame
        return self.state()

def f32down(x):
    """IEEE single rounding toward -inf (game CW 0x077f stores)."""
    import math
    r = struct.unpack('<f', struct.pack('<f', x))[0] if abs(x) < 3.4e38 else x
    if r > x:
        b = struct.unpack('<I', struct.pack('<f', r))[0]
        if r > 0: b -= 1
        elif r == 0: b = 0x80000001
        else: b += 1
        r = struct.unpack('<f', struct.pack('<I', b))[0]
    return r

ENGINE = 0xc12030 + 0xc      # 0051a000(): engine/driveline object of the player car
def engine_frame(m, rate=36):
    """Subset of per-frame 0051aac0: ignition/shift cut timer (+0x550) countdown at task rate.
    Fuel burn, damage misfire and engine thermal of 0051aac0 are Stage 11 and not applied."""
    t = m.f32(ENGINE + 0x550)
    if t > 0:
        t = f32down(t - f32down(1.0 / rate))
        m.wf(ENGINE + 0x550, 0.0 if t < 0 else t)

def flat(z=0.0, surface=1):
    return [dict(normal=(0.0, 0.0, 1.0), d=-z, surface=surface) for _ in range(4)]


# ---------------------------------------------------------------------------------------------
# Driver layer (Stage 7): per-frame 00551e80 tail (hand port, same arithmetic as the Luau host)
# + per-tick ORIGINAL 005539c0 (input ramps, toe, 00553d70 shift FSM/auto clutch, gear, rev
# limiter, predictor) executed in the emulator. Steering ratio/shaping (Stage 12) is replaced by
# a provisional road-wheel target supplied by the host (same as the Luau host).
TICKS_PER_FRAME = 8

def _w(m, a, v): m.wf(a, f32down(v))   # float32 store, RC toward -inf

class OriginalDriver(Original):
    def __init__(self, *a, **k):
        super().__init__(*a, **k)
        m = self.m
        m.uc.mem_write(0xbf6e04, b'\x01')                      # 00551880: player vehicle active
        m.w32(0xbf6e9c, TICKS_PER_FRAME)                       # 00555140: ticks per frame
        self.tick = 0

    def frame(self, c):
        m = self.m; N = float(m.i32(0xbf6e9c))
        _w(m, 0xbf6390, c.get('throttle', 0.0)); _w(m, 0xbf6eac, c.get('brake', 0.0)); _w(m, 0xbf6eb0, c.get('clutch', 0.0))
        for w in range(4):                                      # per-frame tire accumulators (00551e80)
            t = 0xbf3a20 + w * 0xa39
            for o in (0x2ac, 0x2b0, 0x2b4, 0x2b8, 0x2d0, 0x2d4, 0x2bc, 0x2c0): m.w32(t + o, 0)
        target = c.get('steer', 0.0)                            # PROVISIONAL (Stage 12): road-wheel angle
        _w(m, 0xbf63b8, target)
        m.w32(0xbf6e38, m.u32(0xbf6eb0))
        m.w32(0xbf63c0, m.u32(0xbf6e80)); m.w32(0xbf636c, m.u32(0xbf6e64))
        m.w32(0xbf6ea4, m.u32(0xbf6e60)); m.w32(0xbf6e14, m.u32(0xbf6e68))
        thr, brk = m.f32(0xbf6390), m.f32(0xbf6eac)
        _w(m, 0xbf6e30, thr * thr); _w(m, 0xbf6e34, brk * brk)
        _w(m, 0xbf6e88, (target - m.f32(0xbf6e80)) / N)
        _w(m, 0xbf6394, (m.f32(0xbf6e30) - m.f32(0xbf6e60)) / N)
        _w(m, 0xbf6358, (m.f32(0xbf6e34) - m.f32(0xbf6e64)) / N)
        cl = m.f32(0xbf6eb0) - m.f32(0xbf6e68)
        m.uc.mem_write(0xbf6e58, bytes(m.uc.mem_read(0xbf6e28, 36)))
        _w(m, 0xbf6e50, cl / N)
        _w(m, 0xbf6e80, target)
        if m.i32(0xbf6f0c) != 2 and m.i32(0xbf63cc) == 0 and m.i32(0x74c974) != 0 and m.i32(0xbf6f0c) == 0:
            d = (1 if c.get('shiftUp') else 0) - (1 if c.get('shiftDown') else 0)
            if d != 0 and m.i32(0xbf6ea0) in (0, 3, 4):        # 00552450 / 00552480
                m.w32(0xbf63cc, 1 if d > 0 else 5); m.w32(0xbf6e98, 0)

    def drive_tick(self, contacts):
        m = self.m
        m.w32(0xe8441c, self.tick % TICKS_PER_FRAME)
        m.uc.mem_write(0xe843fc, b'\x01')
        m.call(0x5539c0)                                        # ORIGINAL tick input + predictor + export
        self.tires(contacts); m.call(0x5b2bd0)
        m.uc.mem_write(0xe843fc, b'\x00')
        m.call(0x5b2be0); m.w32(0xe847c8, STATE); m.call(0x5b2cb0, STATE, self.root)
        self.tires(contacts); m.call(0x5b2bd0)
        m.call(0x5b2c00)
        self.tick += 1

    def state(self):
        # export into a host scratch block (keeps the game's state block bf6d40 untouched)
        m = self.m; S = 0xf7f100 + 0x140
        m.call(0x5b2cb0, S, self.root)
        return [m.f32(S + 4 * i) for i in range(45)]

    def step_driver(self, controls, contacts):
        if self.tick % TICKS_PER_FRAME == 0: self.frame(controls)
        self.drive_tick(contacts)
        if self.tick % TICKS_PER_FRAME == 0: engine_frame(self.m)
        return self.state()
